content.text:
{
  "name": "低温制冷机监测系统",
  "name_en": "Cryogenic Refrigerator Monitor",
  "manufacturer": "",
  "description": "用于监测实验室低温制冷机或低温恒温器运行状态的仪器。它通常用于低温物理、量子器件和超导实验中，帮助研究人员查看制冷系统的当前状态与关键监测信息。",
  "description_en": "An instrument used to monitor the operating status of a cryogenic refrigerator or cryostat in the laboratory. It is typically used in low-temperature physics, quantum-device, and superconducting experiments to let researchers check the current state and key monitored information of the cooling system.",
  "actions": [
    {
      "action_name": "auto-snapshot",
      "description": "获取当前监测参数快照",
      "description_en": "Acquire a snapshot of the current monitored parameters"
    },
    {
      "action_name": "auto-get_idn",
      "description": "获取设备标识信息",
      "description_en": "get device identification information"
    }
  ],
  "tag_hints": [
    "cryogenic refrigerator monitoring",
    "cryostat status monitoring",
    "low-temperature experiments",
    "laboratory refrigeration system",
    "instrument identification"
  ]
}

